21	namespace vortex {
22	
23	static inline uint32_t bit(uint32_t x, int b) { return (x >> b) & 1u; }
24	static inline uint32_t bits(uint32_t x, int hi, int lo) { return (x >> lo) & ((1u << (hi - lo + 1)) - 1u); }
25	static inline uint32_t sext_imm(uint32_t val, int width) {
26	    uint32_t m = 1u << (width - 1);
27	    return (val ^ m) - m;
28	}
29	
30	// compressed register mapping: rd' (3 bits) -> x8..x15
31	static inline uint32_t rcp(uint32_t r3) { return 8u + r3; }
32	
33	// Build I-type, S-type, U-type, R-type 32-bit encodings (RV32I)
34	static inline uint32_t ENCI(uint32_t imm12, uint32_t rs1, uint32_t funct3, uint32_t rd, uint32_t opcode) {
35	    return ((imm12 & 0xFFF) << 20) | ((rs1 & 31) << 15) | ((funct3 & 7) << 12) | ((rd & 31) << 7) | (opcode & 0x7F);
36	}
37	static inline uint32_t ENCR(uint32_t funct7, uint32_t rs2, uint32_t rs1, uint32_t funct3, uint32_t rd, uint32_t opcode) {
38	    return ((funct7 & 0x7F) << 25) | ((rs2 & 31) << 20) | ((rs1 & 31) << 15) | ((funct3 & 7) << 12) | ((rd & 31) << 7) | (opcode & 0x7F);
39	}
40	static inline uint32_t ENCS(uint32_t imm12, uint32_t rs2, uint32_t rs1, uint32_t funct3, uint32_t opcode) {
41	    uint32_t imm11_5 = (imm12 >> 5) & 0x7F;
42	    uint32_t imm4_0  = imm12 & 0x1F;
43	    return (imm11_5 << 25) | ((rs2 & 31) << 20) | ((rs1 & 31) << 15) | ((funct3 & 7) << 12) | (imm4_0 << 7) | (opcode & 0x7F);
44	}
45	static inline uint32_t ENCU(uint32_t imm20, uint32_t rd, uint32_t opcode) {
46	    return ((imm20 & 0xFFFFF) << 12) | ((rd & 31) << 7) | (opcode & 0x7F);
47	}
48	static inline uint32_t ENCUJ(uint32_t imm21, uint32_t rd, uint32_t opcode) { // JAL
49	    // J-type bit shuffle: [20|10:1|11|19:12]
50	    uint32_t i = imm21 & 0x001FFFFF;
51	    uint32_t enc = ((i & (1<<20)) << 11)         // 20 -> 31
52	                 | ((i & 0x000007FE) << 20)      // 10:1 -> 30:21
53	                 | ((i & (1<<11)) << 9)          // 11 -> 20
54	                 | ((i & 0x000FF000));           // 19:12 -> 19:12
55	    return enc | ((rd & 31) << 7) | (opcode & 0x7F);
56	}
57	static inline uint32_t ENCB(uint32_t imm13, uint32_t rs2, uint32_t rs1, uint32_t funct3, uint32_t opcode) {
58	    // B-type: imm[12|10:5|4:1|11] -> [31|30:25|11:8|7]
59	    uint32_t i = imm13 & 0x1FFF;
60	    uint32_t imm12 = (i >> 12) & 1;
61	    uint32_t imm10_5 = (i >> 5) & 0x3F;
62	    uint32_t imm4_1 = (i >> 1) & 0xF;
63	    uint32_t imm11 = (i >> 11) & 1;
64	    uint32_t enc = (imm12 << 31) | (imm10_5 << 25) | ((rs2 & 31) << 20) | ((rs1 & 31) << 15) |
65	                   ((funct3 & 7) << 12) | (imm4_1 << 8) | (imm11 << 7) | (opcode & 0x7F);
66	    return enc;
67	}
