69	// --- main ---------------------------------------------------------------
70	
71	DecompResult rvc_decompress(uint32_t word) {
72	    DecompResult out{};
73	
74	    if ((word & 0x3) == 0x3) {
75	        out.instr32 = word;
76	        out.size    = 4;
77	        out.illegal = false;
78	        return out;
79	    }
80	
81	    // 16-bit compressed
82	    const uint16_t h = static_cast<uint16_t>(word & 0xFFFF);
83	    const uint32_t quadrant = h & 0x3;              // 0,1,2
84	    const uint32_t funct3   = (h >> 13) & 0x7;
85	
86	    out.size    = 2;
87	    out.illegal = false;
88	
89	    switch (quadrant) {
90	    // ---------------- Quadrant 0 (opcode 00) ----------------
91	    case 0:
92	        switch (funct3) {
93	        case 0b000: { // C.ADDI4SPN -> ADDI rd', x2, nzimm
94	            uint32_t rd_ = rcp(bits(h, 4, 2));
95	            uint32_t nzuimm = (bits(h, 12, 11) << 4) | (bits(h,10, 7) << 6) | (bit(h, 5) << 3) | (bit(h, 6) << 2);
96	            if (nzuimm == 0) { out.illegal = true; break; }
97	            out.instr32 = ENCI(nzuimm, 2, 0b000, rd_, 0b0010011);
98	            break;
99	        }
100	        case 0b001: { // C.FLD (RV32DC/RV64DC) -> FLD rd', uimm(rs1')
101	            uint32_t rd_  = rcp(bits(h, 4, 2));
102	            uint32_t rs1_ = rcp(bits(h, 9, 7));
103	            uint32_t uimm = (bits(h, 12, 10) << 3) | (bits(h, 6, 5) << 6);
104	            out.instr32 = ENCI(uimm, rs1_, 0b011, rd_, 0b0000111);
105	            break;
106	        }
107	        case 0b010: { // C.LW -> LW rd', offset(rs1')
108	            uint32_t rd_  = rcp(bits(h, 4, 2));
109	            uint32_t rs1_ = rcp(bits(h, 9, 7));
110	            uint32_t uimm = (bit(h, 5) << 6) | (bits(h, 12, 10) << 3) | (bit(h, 6) << 2);
111	            out.instr32 = ENCI(uimm, rs1_, 0b010, rd_, 0b0000011);
112	            break;
113	        }
114	        case 0b101: { // C.FSD (RV32DC/RV64DC) -> FSD rs2', uimm(rs1')
115	            uint32_t rs2_ = rcp(bits(h, 4, 2));
116	            uint32_t rs1_ = rcp(bits(h, 9, 7));
117	            uint32_t uimm = (bits(h, 12, 10) << 3) | (bits(h, 6, 5) << 6);
118	            out.instr32 = ENCS(uimm, rs2_, rs1_, 0b011, 0b0100111);
119	            break;
120	        }
121	        case 0b011: {
122	#ifdef VX_CFG_XLEN_64
123	            // RV64C: C.LD -> LD rd', uimm(rs1')
124	            uint32_t rd_  = rcp(bits(h, 4, 2));
125	            uint32_t rs1_ = rcp(bits(h, 9, 7));
126	            uint32_t uimm = (bits(h, 12, 10) << 3) | (bits(h, 6, 5) << 6);
127	            out.instr32 = ENCI(uimm, rs1_, 0b011, rd_, 0b0000011);
128	#else
129	            // RV32FC: C.FLW -> FLW rd', offset(rs1')
130	            uint32_t rd_  = rcp(bits(h, 4, 2));
131	            uint32_t rs1_ = rcp(bits(h, 9, 7));
132	            uint32_t uimm = (bit(h, 5) << 6) | (bits(h, 12, 10) << 3) | (bit(h, 6) << 2);
133	            out.instr32 = ENCI(uimm, rs1_, 0b010, rd_, 0b0000111);
134	#endif
135	            break;
136	        }
137	        case 0b110: { // C.SW -> SW rs2', offset(rs1')
138	            uint32_t rs2_ = rcp(bits(h, 4, 2));
139	            uint32_t rs1_ = rcp(bits(h, 9, 7));
140	            uint32_t uimm = (bit(h, 5) << 6) | (bits(h, 12, 10) << 3) | (bit(h, 6) << 2);
141	            out.instr32 = ENCS(uimm, rs2_, rs1_, 0b010, 0b0100011);
142	            break;
143	        }
144	        case 0b111: {
145	#ifdef VX_CFG_XLEN_64
146	            // RV64C: C.SD -> SD rs2', uimm(rs1')
147	            uint32_t rs2_ = rcp(bits(h, 4, 2));
148	            uint32_t rs1_ = rcp(bits(h, 9, 7));
149	            uint32_t uimm = (bits(h, 12, 10) << 3) | (bits(h, 6, 5) << 6);
150	            out.instr32 = ENCS(uimm, rs2_, rs1_, 0b011, 0b0100011);
151	#else
152	            // RV32FC: C.FSW -> FSW rs2', offset(rs1')
153	            uint32_t rs2_ = rcp(bits(h, 4, 2));
154	            uint32_t rs1_ = rcp(bits(h, 9, 7));
155	            uint32_t uimm = (bit(h, 5) << 6) | (bits(h, 12, 10) << 3) | (bit(h, 6) << 2);
156	            out.instr32 = ENCS(uimm, rs2_, rs1_, 0b010, 0b0100111);
157	#endif
158	            break;
159	        }
160	        default:
161	            out.illegal = true; break;
162	        }
163	        break;
164	
165	    // ---------------- Quadrant 1 (opcode 01) ----------------
166	    case 1:
167	        switch (funct3) {
168	        case 0b000: { // C.ADDI -> ADDI rd, rd, imm  (and C.NOP when rd=0,imm=0)
169	            uint32_t rd = bits(h, 11, 7);
170	            int32_t imm = static_cast<int32_t>(sext_imm(((bit(h,12)<<5) | bits(h,6,2)), 6));
171	            out.instr32 = ENCI(imm & 0xFFF, rd, 0b000, rd, 0b0010011);
172	            if (rd == 0 && imm == 0) {
173	                out.illegal = false;
174	                out.instr32 = ENCI(0, 0, 0b000, 0, 0b0010011); // C.NOP -> ADDI x0,x0,0
175	            }
176	            break;
177	        }
178	        case 0b001: {
179	#ifdef VX_CFG_XLEN_64
180	            // RV64C: C.ADDIW -> ADDIW rd, rd, imm (rd != 0)
181	            uint32_t rd = bits(h, 11, 7);
182	            int32_t imm = static_cast<int32_t>(sext_imm(((bit(h,12)<<5) | bits(h,6,2)), 6));
183	            if (rd == 0) { out.illegal = true; break; }
184	            out.instr32 = ENCI(imm & 0xFFF, rd, 0b000, rd, 0b0011011);
185	#else
186	            // RV32C: C.JAL -> JAL x1, imm
187	            uint32_t imm =
188	                (bit(h,12)<<11) | (bit(h,8)<<10) | (bits(h,10,9)<<8) | (bit(h,6)<<7) |
189	                (bit(h,7)<<6) | (bit(h,2)<<5) | (bit(h,11)<<4) | (bits(h,5,3)<<1);
190	            int32_t simm = static_cast<int32_t>(sext_imm(imm, 12));
191	            uint32_t imm21 = static_cast<uint32_t>(simm) & 0x001FFFFF;
192	            out.instr32 = ENCUJ(imm21, 1, 0b1101111);
193	#endif
194	            break;
195	        }
196	        case 0b010: { // C.LI -> ADDI rd, x0, imm (rd=x0 is HINT, treat as NOP)
197	            uint32_t rd = bits(h, 11, 7);
198	            int32_t imm = static_cast<int32_t>(sext_imm(((bit(h,12)<<5) | bits(h,6,2)), 6));
199	            out.instr32 = ENCI(imm & 0xFFF, 0, 0b000, rd, 0b0010011);
200	            break;
201	        }
202	        case 0b011: {
203	            uint32_t rd = bits(h, 11, 7);
204	            if (rd == 2) {
205	                // C.ADDI16SP -> ADDI x2, x2, imm
206	                int32_t imm = (bit(h,12)<<9) | (bit(h,6)<<4) | (bit(h,5)<<6) | (bits(h,4,3)<<7) | (bit(h,2)<<5);
207	                imm = static_cast<int32_t>(sext_imm(imm, 10));
208	                if (imm == 0) { out.illegal = true; break; }
209	                out.instr32 = ENCI(imm & 0xFFF, 2, 0b000, 2, 0b0010011);
210	            } else {
211	                // C.LUI -> LUI rd, imm (rd != x0, x2)
212	                int32_t imm = static_cast<int32_t>(sext_imm((bit(h,12)<<17) | (bits(h,6,2)<<12), 18));
213	                if (rd == 0 || rd == 2 || imm == 0) { out.illegal = true; break; }
214	                out.instr32 = ENCU((imm >> 12), rd, 0b0110111);
215	            }
216	            break;
217	        }
218	        case 0b100: {
219	            uint32_t subfunct = bits(h, 11, 10);
220	            if (subfunct == 0b00) { // C.SRLI
221	                uint32_t rd_ = rcp(bits(h,9,7));
222	                uint32_t sh  = (bit(h,12)<<5) | bits(h,6,2);
223	                out.instr32 = ENCI(sh, rd_, 0b101, rd_, 0b0010011);
224	            } else if (subfunct == 0b01) { // C.SRAI
225	                uint32_t rd_ = rcp(bits(h,9,7));
226	                uint32_t sh  = (bit(h,12)<<5) | bits(h,6,2);
227	                out.instr32 = ENCI(sh, rd_, 0b101, rd_, 0b0010011) | (0x40000000u);
228	            } else if (subfunct == 0b10) { // C.ANDI
229	                uint32_t rd_ = rcp(bits(h,9,7));
230	                int32_t imm = static_cast<int32_t>(sext_imm(((bit(h,12)<<5) | bits(h,6,2)), 6));
231	                out.instr32 = ENCI(imm & 0xFFF, rd_, 0b111, rd_, 0b0010011);
232	            } else { // 0b11: C.SUB/XOR/OR/AND, or RV64C C.SUBW/C.ADDW (bit12=1)
233	                uint32_t rd_  = rcp(bits(h,9,7));
234	                uint32_t rs2_ = rcp(bits(h,4,2));
235	                uint32_t op2  = bits(h, 6,5);
236	                if (bit(h,12) == 0) {
237	                    switch (op2) {
238	                        case 0b00: out.instr32 = ENCR(0b0100000, rs2_, rd_, 0b000, rd_, 0b0110011); break; // C.SUB
239	                        case 0b01: out.instr32 = ENCR(0b0000000, rs2_, rd_, 0b100, rd_, 0b0110011); break; // C.XOR
240	                        case 0b10: out.instr32 = ENCR(0b0000000, rs2_, rd_, 0b110, rd_, 0b0110011); break; // C.OR
241	                        case 0b11: out.instr32 = ENCR(0b0000000, rs2_, rd_, 0b111, rd_, 0b0110011); break; // C.AND
242	                    }
243	                } else {
244	#ifdef VX_CFG_XLEN_64
245	                    switch (op2) {
246	                        case 0b00: out.instr32 = ENCR(0b0100000, rs2_, rd_, 0b000, rd_, 0b0111011); break; // C.SUBW
247	                        case 0b01: out.instr32 = ENCR(0b0000000, rs2_, rd_, 0b000, rd_, 0b0111011); break; // C.ADDW
248	                        default:   out.illegal = true; break;
249	                    }
250	#else
251	                    out.illegal = true;
252	#endif
253	                }
254	            }
255	            break;
256	        }
257	        case 0b101: { // C.J -> JAL x0, imm
258	            uint32_t imm =
259	                (bit(h,12)<<11) | (bit(h,8)<<10) | (bits(h,10,9)<<8) | (bit(h,6)<<7) |
260	                (bit(h,7)<<6) | (bit(h,2)<<5) | (bit(h,11)<<4) | (bits(h,5,3)<<1);
261	            int32_t simm = static_cast<int32_t>(sext_imm(imm, 12));
262	            uint32_t imm21 = static_cast<uint32_t>(simm) & 0x001FFFFF;
263	            out.instr32 = ENCUJ(imm21, 0, 0b1101111);
264	            break;
265	        }
266	        case 0b110: { // C.BEQZ
267	            uint32_t rs1_ = rcp(bits(h, 9,7));
268	            uint32_t imm = (bit(h,12)<<8) | (bit(h,6)<<7) | (bit(h,5)<<6) | (bit(h,2)<<5) | (bits(h,11,10)<<3) | (bits(h,4,3)<<1);
269	            int32_t simm = static_cast<int32_t>(sext_imm(imm, 9));
270	            uint32_t imm13 = static_cast<uint32_t>(simm) & 0x1FFF;
271	            out.instr32 = ENCB(imm13, 0, rs1_, 0b000, 0b1100011);
272	            break;
273	        }
274	        case 0b111: { // C.BNEZ
275	            uint32_t rs1_ = rcp(bits(h, 9,7));
276	            uint32_t imm = (bit(h,12)<<8) | (bit(h,6)<<7) | (bit(h,5)<<6) | (bit(h,2)<<5) | (bits(h,11,10)<<3) | (bits(h,4,3)<<1);
277	            int32_t simm = static_cast<int32_t>(sext_imm(imm, 9));
278	            uint32_t imm13 = static_cast<uint32_t>(simm) & 0x1FFF;
279	            out.instr32 = ENCB(imm13, 0, rs1_, 0b001, 0b1100011);
280	            break;
281	        }
282	        default:
283	            out.illegal = true; break;
284	        }
285	        break;
286	
287	    // ---------------- Quadrant 2 (opcode 10) ----------------
288	    case 2:
289	        switch (funct3) {
290	        case 0b000: { // C.SLLI
291	            uint32_t rd = bits(h, 11, 7);
292	            uint32_t sh = (bit(h,12)<<5) | bits(h,6,2);
293	            if (rd == 0) { out.illegal = true; break; }
294	            out.instr32 = ENCI(sh, rd, 0b001, rd, 0b0010011);
295	            break;
296	        }
297	        case 0b001: { // C.FLDSP (RV32DC/RV64DC) -> FLD rd, uimm(x2)
298	            uint32_t rd = bits(h, 11, 7);
299	            uint32_t uimm = (bit(h, 12) << 5) | (bits(h, 6, 5) << 3) | (bits(h, 4, 2) << 6);
300	            out.instr32 = ENCI(uimm, 2, 0b011, rd, 0b0000111);
301	            break;
302	        }
303	        case 0b101: { // C.FSDSP (RV32DC/RV64DC) -> FSD rs2, uimm(x2)
304	            uint32_t rs2 = bits(h, 6, 2);
305	            uint32_t uimm = (bits(h, 12, 10) << 3) | (bits(h, 9, 7) << 6);
306	            out.instr32 = ENCS(uimm, rs2, 2, 0b011, 0b0100111);
307	            break;
308	        }
309	        case 0b010: { // C.LWSP
310	            uint32_t rd = bits(h, 11, 7);
311	            if (rd == 0) { out.illegal = true; break; }
312	            uint32_t uimm = (bit(h, 12) << 5) | (bits(h, 6, 4) << 2) | (bits(h, 3, 2) << 6);
313	            out.instr32 = ENCI(uimm, 2, 0b010, rd, 0b0000011);
314	            break;
315	        }
316	#ifdef VX_CFG_XLEN_64
317	        case 0b011: { // RV64C: C.LDSP -> LD rd, uimm(x2), rd != 0
318	            uint32_t rd = bits(h, 11, 7);
319	            if (rd == 0) { out.illegal = true; break; }
320	            uint32_t uimm = (bit(h, 12) << 5) | (bits(h, 6, 5) << 3) | (bits(h, 4, 2) << 6);
321	            out.instr32 = ENCI(uimm, 2, 0b011, rd, 0b0000011);
322	            break;
323	        }
324	#else
325	        case 0b011: { // RV32FC: C.FLWSP -> FLW rd, uimm(x2)
326	            uint32_t rd = bits(h, 11, 7);
327	            uint32_t uimm = (bit(h, 12) << 5) | (bits(h, 6, 4) << 2) | (bits(h, 3, 2) << 6);
328	            out.instr32 = ENCI(uimm, 2, 0b010, rd, 0b0000111);
329	            break;
330	        }
331	#endif
332	        case 0b100: {
333	            uint32_t rd  = bits(h, 11, 7);
334	            uint32_t rs2 = bits(h, 6, 2);
335	            uint32_t s12 = bit(h, 12);
336	            if (rs2 == 0) {
337	                if (s12 == 0) {
338	                    // C.JR
339	                    if (rd == 0) { out.illegal = true; break; }
340	                    out.instr32 = ENCI(0, rd, 0b000, 0, 0b1100111);
341	                } else {
342	                    if (rd == 0) {
343	                        // C.EBREAK
344	                        out.instr32 = 0x00100073;
345	                    } else {
346	                        // C.JALR
347	                        out.instr32 = ENCI(0, rd, 0b000, 1, 0b1100111);
348	                    }
349	                }
350	            } else {
351	                if (rd == 0) { out.illegal = true; break; }
352	                if (s12 == 0) {
353	                    // C.MV
354	                    out.instr32 = ENCR(0b0000000, rs2, 0, 0b000, rd, 0b0110011);
355	                } else {
356	                    // C.ADD
357	                    out.instr32 = ENCR(0b0000000, rs2, rd, 0b000, rd, 0b0110011);
358	                }
359	            }
360	            break;
361	        }
362	        case 0b110: { // C.SWSP
363	            uint32_t rs2 = bits(h, 6, 2);
364	            uint32_t imm = (bits(h, 12, 9) << 2) | (bits(h, 8, 7)  << 6);
365	            out.instr32 = ENCS(imm, rs2, 2, 0b010, 0b0100011);
366	            break;
367	        }
368	#ifdef VX_CFG_XLEN_64
369	        case 0b111: { // RV64C: C.SDSP -> SD rs2, uimm(x2)
370	            uint32_t rs2 = bits(h, 6, 2);
371	            uint32_t uimm = (bits(h, 12, 10) << 3) | (bits(h, 9, 7) << 6);
372	            out.instr32 = ENCS(uimm, rs2, 2, 0b011, 0b0100011);
373	            break;
374	        }
375	#else
376	        case 0b111: { // RV32FC: C.FSWSP -> FSW rs2, uimm(x2)
377	            uint32_t rs2 = bits(h, 6, 2);
378	            uint32_t uimm = (bits(h, 12, 9) << 2) | (bits(h, 8, 7) << 6);
379	            out.instr32 = ENCS(uimm, rs2, 2, 0b010, 0b0100111);
380	            break;
381	        }
382	#endif
383	        default:
384	            out.illegal = true; break;
385	        }
386	        break;
387	
388	    default:
389	        out.illegal = true; break;
390	    }
391	    if (out.illegal) {
392	        std::cerr << "Illegal 16-bit RVC: word=0x" << std::hex << (word & 0xFFFFu) << std::dec
393	                  << ", quadrant=" << quadrant << ", func3=" << funct3 << std::endl;
394	    }
395	    return out;
396	}
