398	// ---------------------------------------------------------------------------
399	// Decompressor — per-core RVC fetch SimObject
400	// ---------------------------------------------------------------------------
401	
402	Decompressor::Decompressor(const SimContext& ctx, const char* name, uint32_t num_warps)
403	    : SimObject<Decompressor>(ctx, name)
404	    , state_(num_warps)
405	{}
406	
407	Decompressor::~Decompressor() {}
408	
409	void Decompressor::on_reset() {
410	    for (auto& s : state_) s = RvcSlot{};
411	    while (!refetch_queue_.empty()) refetch_queue_.pop();
412	}
413	
414	Decompressor::Pick Decompressor::pick_request(instr_trace_t* fetch_latch_head) {
415	    Pick out{};
416	    if (!refetch_queue_.empty()) {
417	        // Cross-word completion in flight — drain its second fetch first.
418	        out.trace = refetch_queue_.front();
419	        const auto& rvc = state_.at(out.trace->wid);
420	        out.addr = (rvc.inst_pc & ~Word(3)) + 4;
421	        out.from_refetch = true;
422	    } else if (fetch_latch_head != nullptr) {
423	        out.trace = fetch_latch_head;
424	        out.addr  = fetch_latch_head->PC & ~Word(3);
425	        out.from_refetch = false;
426	    }
427	    return out;
428	}
429	
430	void Decompressor::commit_request(bool from_refetch) {
431	    if (from_refetch && !refetch_queue_.empty()) {
432	        refetch_queue_.pop();
433	    }
434	}
435	
436	Word Decompressor::fetch_addr(const instr_trace_t* trace) const {
437	    const auto& rvc = state_.at(trace->wid);
438	    if (rvc.needs_second) {
439	        return (rvc.inst_pc & ~Word(3)) + 4;
440	    }
441	    return trace->PC & ~Word(3);
442	}
443	
444	bool Decompressor::on_icache_rsp(instr_trace_t* trace, const mem_block_t& line) {
445	    // Extract the 4-byte word at the address we fetched. fetch_addr()
446	    // factors in whether this rsp is a refetch completion (high half of a
447	    // cross-word 32b) or a fresh fetch.
448	    uint32_t line_offset = fetch_addr(trace) & (VX_CFG_MEM_BLOCK_SIZE - 1);
449	    uint32_t word = 0;
450	    std::memcpy(&word, line.data() + line_offset, sizeof(uint32_t));
451	
452	    auto& rvc = state_.at(trace->wid);
453	
454	    if (rvc.needs_second) {
455	        // Combine: low half from buffer, high half = low16 of new word.
456	        uint16_t high = word & 0xFFFFu;
457	        trace->code = (uint32_t(high) << 16) | rvc.low_half;
458	        rvc = RvcSlot{};
459	        return true;
460	    }
461	
462	    // Halfword at PC depends on PC[1].
463	    uint16_t hword = (trace->PC & Word(2)) ? uint16_t(word >> 16)
464	                                            : uint16_t(word & 0xFFFFu);
465	    if ((hword & 0x3u) != 0x3u) {
466	        // 16-bit RVC: emit the raw hword zero-extended; the decoder
467	        // detects RVC from code[1:0] and decompresses internally.
468	        trace->code = uint32_t(hword);
469	        return true;
470	    }
471	    if ((trace->PC & Word(2)) == 0) {
472	        // 4-byte aligned 32-bit: full word at PC is the instruction.
473	        trace->code = word;
474	        return true;
475	    }
476	    // 2-byte aligned 32-bit: low half = high16 of fetched word; high half
477	    // lives in the next aligned word — buffer + queue for refetch.
478	    rvc.needs_second = true;
479	    rvc.low_half     = uint16_t(word >> 16);
480	    rvc.inst_pc      = trace->PC;
481	    refetch_queue_.push(trace);
482	    return false;
483	}
484	
485	} // namespace vortex
