37	static op_string_t op_string(const Instr &instr) {
38	  auto op_type = instr.get_op_type();
39	  auto instrArgs = instr.get_args();
40	  return visit_var(op_type,
41	    [&](AluType alu_type)-> op_string_t {
42	      auto aluArgs = std::get<IntrAluArgs>(instrArgs);
43	      switch (alu_type) {
44	      case AluType::LUI:   return {"LUI", to_hex_str(aluArgs.imm)};
45	      case AluType::AUIPC: return {"AUIPC", to_hex_str(aluArgs.imm)};
46	      case AluType::ADD: {
47	        if (aluArgs.is_imm) {
48	          return {aluArgs.is_w ? "ADDIW":"ADDI", to_hex_str(aluArgs.imm)};
49	        } else {
50	          return {aluArgs.is_w ? "ADDW":"ADD", ""};
51	        }
52	      }
53	      case AluType::SUB: {
54	        if (aluArgs.is_imm) {
55	          return {aluArgs.is_w ? "SUBW":"SUB", to_hex_str(aluArgs.imm)};
56	        } else {
57	          return {aluArgs.is_w ? "SUBW":"SUB", ""};
58	        }
59	      }
60	      case AluType::SLL: {
61	        if (aluArgs.is_imm) {
62	          return {aluArgs.is_w ? "SLLIW":"SLLI", to_hex_str(aluArgs.imm)};
63	        } else {
64	          return {aluArgs.is_w ? "SLLW":"SLL", ""};
65	        }
66	      }
67	      case AluType::SRL: {
68	        if (aluArgs.is_imm) {
69	          return {aluArgs.is_w ? "SRLIW":"SRLI", to_hex_str(aluArgs.imm)};
70	        } else {
71	          return {aluArgs.is_w ? "SRLW":"SRL", ""};
72	        }
73	      }
74	      case AluType::SRA: {
75	        if (aluArgs.is_imm) {
76	          return {aluArgs.is_w ? "SRAIW":"SRAI", to_hex_str(aluArgs.imm)};
77	        } else {
78	          return {aluArgs.is_w ? "SRAW":"SRA", ""};
79	        }
80	      }
81	      case AluType::SLT: {
82	        if (aluArgs.is_imm) {
83	          return {"SLTI", to_hex_str(aluArgs.imm)};
84	        } else {
85	          return {"SLT", ""};
86	        }
87	      }
88	      case AluType::SLTU: {
89	        if (aluArgs.is_imm) {
90	          return {"SLTIU", to_hex_str(aluArgs.imm)};
91	        } else {
92	          return {"SLTU", ""};
93	        }
94	      }
95	      case AluType::AND: {
96	        if (aluArgs.is_imm) {
97	          return {"ANDI", to_hex_str(aluArgs.imm)};
98	        } else {
99	          return {"AND", ""};
100	        }
101	      }
102	      case AluType::OR: {
103	        if (aluArgs.is_imm) {
104	          return {"ORI", to_hex_str(aluArgs.imm)};
105	        } else {
106	          return {"OR", ""};
107	        }
108	      }
109	      case AluType::XOR: {
110	        if (aluArgs.is_imm) {
111	          return {"XORI", to_hex_str(aluArgs.imm)};
112	        } else {
113	          return {"XOR", ""};
114	        }
115	      }
116	      case AluType::CZERO: return {aluArgs.imm ? "CZERO.NEZ":"CZERO.EQZ", ""};
117	      default:
118	        std::abort();
119	      }
120	    },
121	    [&](VoteType vote_type)-> op_string_t {
122	      switch (vote_type) {
123	      case VoteType::ALL: return {"VOTE.ALL", ""};
124	      case VoteType::ANY: return {"VOTE.ANY", ""};
125	      case VoteType::UNI: return {"VOTE.UNI", ""};
126	      case VoteType::BAL: return {"VOTE.BAL", ""};
127	      default:
128	        std::abort();
129	      }
130	    },
131	    [&](ShflType shfl_type)-> op_string_t {
132	      switch (shfl_type) {
133	      case ShflType::UP:   return {"SHFL.UP", ""};
134	      case ShflType::DOWN: return {"SHFL.DOWN", ""};
135	      case ShflType::BFLY: return {"SHFL.BFLY", ""};
136	      case ShflType::IDX:  return {"SHFL.IDX", ""};
137	      default:
138	        std::abort();
139	      }
140	    },
141	    [&](WgatherType)-> op_string_t {
142	      return {"WGATHER", ""};
143	    },
144	    [&](BrType br_type)-> op_string_t {
145	      auto brArgs = std::get<IntrBrArgs>(instrArgs);
146	      switch (br_type) {
147	      case BrType::BR: {
148	        switch (brArgs.cmp) {
149	        case 0: return {"BEQ",  to_hex_str(brArgs.offset)};
