151	        case 4: return {"BLT",  to_hex_str(brArgs.offset)};
152	        case 5: return {"BGE",  to_hex_str(brArgs.offset)};
153	        case 6: return {"BLTU", to_hex_str(brArgs.offset)};
154	        case 7: return {"BGEU", to_hex_str(brArgs.offset)};
155	        default:
156	          std::abort();
157	        }
158	      }
159	      case BrType::JAL:  return {"JAL", to_hex_str(brArgs.offset)};
160	      case BrType::JALR: return {"JALR", to_hex_str(brArgs.offset)};
161	      case BrType::SYS:
162	        switch (brArgs.offset) {
163	        case 0x000: return {"ECALL", ""};
164	        case 0x001: return {"EBREAK", ""};
165	        case 0x002: return {"URET", ""};
166	        case 0x102: return {"SRET", ""};
167	        case 0x302: return {"MRET", ""};
168	        default:
169	          std::abort();
170	        }
171	      default:
172	        std::abort();
173	      }
174	    },
175	    [&](MdvType mdv_type)-> op_string_t {
176	      auto mdvArgs = std::get<IntrMdvArgs>(instrArgs);
177	      switch (mdv_type) {
178	      case MdvType::MUL:    return {mdvArgs.is_w ? "MULW":"MUL", ""};
179	      case MdvType::MULHU:  return {"MULHU", ""};
180	      case MdvType::MULH:   return {"MULH", ""};
181	      case MdvType::MULHSU: return {"MULHSU", ""};
182	      case MdvType::DIV:    return {mdvArgs.is_w ? "DIVW":"DIV", ""};
183	      case MdvType::DIVU:   return {mdvArgs.is_w ? "DIVUW":"DIVU", ""};
184	      case MdvType::REM:    return {mdvArgs.is_w ? "REMW":"REM", ""};
185	      case MdvType::REMU:   return {mdvArgs.is_w ? "REMUW":"REMU", ""};
186	      default:
187	        std::abort();
188	      }
189	    },
190	    [&](FpuType fpu_type)-> op_string_t {
191	      auto fpuArgs = std::get<IntrFpuArgs>(instrArgs);
192	      switch (fpu_type) {
193	      case FpuType::FADD:   return {fpuArgs.is_f64 ? "FADD.D":"FADD.S", ""};
194	      case FpuType::FSUB:   return {fpuArgs.is_f64 ? "FSUB.D":"FSUB.S", ""};
195	      case FpuType::FMUL:   return {fpuArgs.is_f64 ? "FMUL.D":"FMUL.S", ""};
196	      case FpuType::FDIV:   return {fpuArgs.is_f64 ? "FDIV.D":"FDIV.S", ""};
197	      case FpuType::FSQRT:  return {fpuArgs.is_f64 ? "FSQRT.D":"FSQRT.S", ""};
198	      case FpuType::FMADD:  return {fpuArgs.is_f64 ? "FMADD.D":"FMADD.S", ""};
199	      case FpuType::FMSUB:  return {fpuArgs.is_f64 ? "FMSUB.D":"FMSUB.S", ""};
200	      case FpuType::FNMADD: return {fpuArgs.is_f64 ? "FNMADD.D":"FNMADD.S", ""};
201	      case FpuType::FNMSUB: return {fpuArgs.is_f64 ? "FNMSUB.D":"FNMSUB.S", ""};
202	      case FpuType::F2I: {
203	        switch (fpuArgs.cvt) {
204	        case 0: return {fpuArgs.is_f64 ? "FCVT.W.D":"FCVT.W.S", ""};
205	        case 1: return {fpuArgs.is_f64 ? "FCVT.WU.D":"FCVT.WU.S", ""};
206	        case 2: return {fpuArgs.is_f64 ? "FCVT.L.D":"FCVT.L.S", ""};
207	        case 3: return {fpuArgs.is_f64 ? "FCVT.LU.D":"FCVT.LU.S", ""};
208	        default:
209	          std::abort();
210	        }
211	      }
212	      case FpuType::I2F: {
213	        switch (fpuArgs.cvt) {
214	        case 0: return {fpuArgs.is_f64 ? "FCVT.D.W":"FCVT.S.W", ""};
215	        case 1: return {fpuArgs.is_f64 ? "FCVT.D.WU":"FCVT.S.WU", ""};
216	        case 2: return {fpuArgs.is_f64 ? "FCVT.D.L":"FCVT.S.L", ""};
217	        case 3: return {fpuArgs.is_f64 ? "FCVT.D.LU":"FCVT.S.LU", ""};
218	        default:
219	          std::abort();
220	        }
221	      }
222	      case FpuType::F2F: return {fpuArgs.is_f64 ? "FCVT.D.S":"FCVT.S.D", ""};
223	      case FpuType::FCMP: {
224	        switch (fpuArgs.frm) {
225	        case 0: return {fpuArgs.is_f64 ? "FLE.D":"FLE.S", ""};
226	        case 1: return {fpuArgs.is_f64 ? "FLT.D":"FLT.S", ""};
227	        case 2: return {fpuArgs.is_f64 ? "FEQ.D":"FEQ.S", ""};
