229	          std::abort();
230	        }
231	      }
232	      case FpuType::FSGNJ: {
233	        switch (fpuArgs.frm) {
234	        case 0: return {fpuArgs.is_f64 ? "FSGNJ.D":"FSGNJ.S", ""};
235	        case 1: return {fpuArgs.is_f64 ? "FSGNJN.D":"FSGNJN.S", ""};
236	        case 2: return {fpuArgs.is_f64 ? "FSGNJX.D":"FSGNJX.S", ""};
237	        default:
238	          std::abort();
239	        }
240	      }
241	      case FpuType::FCLASS: return {fpuArgs.is_f64 ? "FCLASS.D":"FCLASS.S", ""};
242	      case FpuType::FMVXW:  return {fpuArgs.is_f64 ? "FMV.X.D":"FMV.X.S", ""};
243	      case FpuType::FMVWX:  return {fpuArgs.is_f64 ? "FMV.D.X":"FMV.S.X", ""};
244	      case FpuType::FMINMAX: {
245	        switch (fpuArgs.frm) {
246	        case 0: return {fpuArgs.is_f64 ? "FMIN.D":"FMIN.S", ""};
247	        case 1: return {fpuArgs.is_f64 ? "FMAX.D":"FMAX.S", ""};
248	        default:
249	          std::abort();
250	        }
251	      }
252	      default:
253	        std::abort();
254	      }
255	    },
256	    [&](LsuType lsu_type)-> op_string_t {
257	      switch (lsu_type) {
258	      case LsuType::LOAD: {
259	        auto lsuArgs = std::get<IntrLsuArgs>(instrArgs);
