299	          case 1: return {"SH", to_hex_str(lsuArgs.offset)};
300	          case 2: return {"SW", to_hex_str(lsuArgs.offset)};
301	          case 3: return {"SD", to_hex_str(lsuArgs.offset)};
302	          default:
303	            std::abort();
304	          }
305	        }
306	      }
307	      case LsuType::FENCE: return {"FENCE", ""};
308	      default:
309	        std::abort();
310	      }
311	    },
312	    [&](AmoType amo_type)-> op_string_t {
313	      auto amoArgs = std::get<IntrAmoArgs>(instrArgs);
314	      switch (amoArgs.width) {
315	      case 2: {
316	        switch (amo_type) {
317	        case AmoType::LR:      return {"LR.W", ""};
318	        case AmoType::SC:      return {"SC.W", ""};
319	        case AmoType::AMOADD:  return {"AMOADD.W", ""};
320	        case AmoType::AMOSWAP: return {"AMOSWAP.W", ""};
321	        case AmoType::AMOAND:  return {"AMOAND.W", ""};
322	        case AmoType::AMOOR:   return {"AMOOR.W", ""};
323	        case AmoType::AMOXOR:  return {"AMOXOR.W", ""};
324	        case AmoType::AMOMIN:  return {"AMOMIN.W", ""};
325	        case AmoType::AMOMAX:  return {"AMOMAX.W", ""};
326	        case AmoType::AMOMINU: return {"AMOMINU.W", ""};
327	        case AmoType::AMOMAXU: return {"AMOMAXU.W", ""};
328	        default:
329	          std::abort();
330	        }
331	      }
332	      case 3: {
333	        switch (amo_type) {
334	        case AmoType::LR:      return {"LR.D", ""};
335	        case AmoType::SC:      return {"SC.D", ""};
336	        case AmoType::AMOADD:  return {"AMOADD.D", ""};
337	        case AmoType::AMOSWAP: return {"AMOSWAP.D", ""};
338	        case AmoType::AMOAND:  return {"AMOAND.D", ""};
339	        case AmoType::AMOOR:   return {"AMOOR.D", ""};
340	        case AmoType::AMOXOR:  return {"AMOXOR.D", ""};
341	        case AmoType::AMOMIN:  return {"AMOMIN.D", ""};
342	        case AmoType::AMOMAX:  return {"AMOMAX.D", ""};
343	        case AmoType::AMOMINU: return {"AMOMINU.D", ""};
344	        case AmoType::AMOMAXU: return {"AMOMAXU.D", ""};
345	        default:
346	          std::abort();
347	        }
348	      }
349	      default:
350	        std::abort();
351	      }
352	    },
353	    [&](CsrType csr_type)-> op_string_t {
354	      auto csrArgs = std::get<IntrCsrArgs>(instrArgs);
355	      if (csrArgs.is_imm) {
356	        switch (csr_type) {
