358	        case CsrType::CSRRS: return {"CSRRSI", to_hex_str(csrArgs.imm) + ", " + to_hex_str(csrArgs.csr)};
359	        case CsrType::CSRRC: return {"CSRRCI", to_hex_str(csrArgs.imm) + ", " + to_hex_str(csrArgs.csr)};
360	        default:
361	          std::abort();
362	        }
363	      } else {
364	        switch (csr_type) {
365	        case CsrType::CSRRW: return {"CSRRW", to_hex_str(csrArgs.csr)};
366	        case CsrType::CSRRS: return {"CSRRS", to_hex_str(csrArgs.csr)};
367	        case CsrType::CSRRC: return {"CSRRC", to_hex_str(csrArgs.csr)};
368	        default:
369	          std::abort();
370	        }
371	      }
372	    },
373	    [&](WctlType wctl_type)-> op_string_t {
374	      auto wctlArgs = std::get<IntrWctlArgs>(instrArgs);
375	      switch (wctl_type) {
