434	std::ostream &operator<<(std::ostream &os, const Instr &instr) {
435	  auto sintr = ::op_string(instr);
436	  int sep = 0;
437	  os << sintr.op;
438	  auto rd = instr.get_dest_reg();
439	  if (rd.type != RegType::None) {
440	    if (sep++ != 0) { os << ", "; } else { os << " "; }
441	    os << rd;
442	  }
443	  for (uint32_t i = 0; i < Instr::MAX_REG_SOURCES; ++i) {
444	    auto rs = instr.get_src_reg(i);
445	    if (rs.type != RegType::None) {
446	      if (sep++ != 0) { os << ", "; } else { os << " "; }
447	      os << rs;
448	    }
449	  }
450	  if (sintr.arg != "") {
451	    if (sep++ != 0) { os << ", "; } else { os << " "; }
452	    os << sintr.arg;
453	  }
454	  if (instr.fu_lock_) {
455	    os << " [fu_lock";
456	    if (instr.fu_unlock_) {
457	      os << ",fu_unlock";
458	    }
459	    os << "]";
460	  }
461	  return os;
462	}
