470	Decoder::~Decoder() {}
471	
472	Instr::Ptr Decoder::decode(uint32_t code, uint64_t uuid) {
473	  // Detect RVC from the raw bits and expand to a 32-bit instruction.
474	  const bool is_rvc = (code & 0x3u) != 0x3u;
475	  if (is_rvc) {
476	    auto r = rvc_decompress(code & 0xFFFFu);
477	    assert(!r.illegal && "illegal RVC encoding");
478	    code = r.instr32;
479	  }
480	  auto op = Opcode((code >> shift_opcode) & mask_opcode);
481	  auto funct2 = (code >> shift_funct2) & mask_funct2;
482	  auto funct3 = (code >> shift_funct3) & mask_funct3;
483	  auto funct5 = (code >> shift_funct5) & mask_funct5;
484	  auto funct6 = (code >> shift_funct6) & mask_funct6;
485	  auto funct7 = (code >> shift_funct7) & mask_funct7;
486	  __unused(funct6);
487	
488	  auto rd  = (code >> shift_rd)  & mask_reg;
489	  auto rs1 = (code >> shift_rs1) & mask_reg;
490	  auto rs2 = (code >> shift_rs2) & mask_reg;
491	  auto rs3 = (code >> shift_rs3) & mask_reg;
492	
493	  auto instr = std::allocate_shared<Instr>(instr_pool_, uuid, FUType::ALU);
494	
495	  switch (op) {
496	  case Opcode::LUI:
497	  case Opcode::AUIPC: { // RV32I: LUI / AUIPC
498	    auto imm20 = (code >> shift_funct3) << shift_funct3;
499	    instr->set_op_type((op == Opcode::LUI) ? AluType::LUI : AluType::AUIPC);
500	    instr->set_args(IntrAluArgs{1, 0, imm20});
501	    instr->set_dest_reg(rd, RegType::Integer);
502	  } break;
503	#ifdef VX_CFG_XLEN_64
504	  case Opcode::R_W:
505	  case Opcode::I_W:
506	#endif
507	  case Opcode::R:
508	  case Opcode::I: {
509	    bool is_w = (op == Opcode::R_W) || (op == Opcode::I_W);
510	    bool is_imm = (op == Opcode::I) || (op == Opcode::I_W);
511	    if (op == Opcode::R && funct7 == 0x7) {
512	      uint32_t imm;
513	      if (funct3 == 0x5) { // CZERO.EQZ
514	        imm = 0;
515	      } else
516	      if (funct3 == 0x7) { // CZERO.NEZ
517	        imm = 1;
518	      } else {
519	        std::abort();
520	      }
521	      instr->set_op_type(AluType::CZERO);
522	      instr->set_args(IntrAluArgs{0, 0, imm});
523	    } else
524	    if ((op == Opcode::R || op == Opcode::R_W) && (funct7 & 0x1)) {
525	      switch (funct3) {
526	      case 0: instr->set_op_type(MdvType::MUL); break;
527	      case 1: instr->set_op_type(MdvType::MULH); break;
528	      case 2: instr->set_op_type(MdvType::MULHSU); break;
529	      case 3: instr->set_op_type(MdvType::MULHU); break;
530	      case 4: instr->set_op_type(MdvType::DIV); break;
531	      case 5: instr->set_op_type(MdvType::DIVU); break;
532	      case 6: instr->set_op_type(MdvType::REM); break;
533	      case 7: instr->set_op_type(MdvType::REMU); break;
534	      default:
535	        std::abort();
536	      }
537	      instr->set_args(IntrMdvArgs{is_w});
538	    } else {
539	      uint32_t imm = 0;
540	      if (funct3 == 0x1 || funct3 == 0x5) {
541	        // Shift instructions
542	        imm = rs2; // uint5
543	      #ifdef VX_CFG_XLEN_64
544	        imm |= ((funct7 & 0x1) << 5);
545	      #endif
546	      } else {
547	        auto imm12 = code >> shift_rs2;
548	        imm = sext(imm12, width_i_imm);
549	      }
550	      switch (funct3) {
551	      case 0: instr->set_op_type((!is_imm && funct7 == 0x20) ? AluType::SUB : AluType::ADD); break;
552	      case 1: instr->set_op_type(AluType::SLL); break;
553	      case 2: instr->set_op_type(AluType::SLT); break;
554	      case 3: instr->set_op_type(AluType::SLTU); break;
555	      case 4: instr->set_op_type(AluType::XOR); break;
556	      // For RV64I SRAI/SRLI with shamt[5]=1, the upper-imm field is funct6
557	      // (bits[31:26]), and bit 25 carries shamt[5] — which makes funct7 read
558	      // back as 0x21 instead of 0x20. Match on funct6 (top 6 bits of funct7)
559	      // so SRAI with shamt >= 32 isn't mis-decoded as SRLI.
560	      case 5: instr->set_op_type((((funct7 >> 1) == 0x10)) ? AluType::SRA : AluType::SRL); break;
561	      case 6: instr->set_op_type(AluType::OR); break;
562	      case 7: instr->set_op_type(AluType::AND); break;
563	      default:
564	        std::abort();
565	      }
566	      instr->set_args(IntrAluArgs{is_imm, is_w, imm});
567	    }
568	    instr->set_dest_reg(rd, RegType::Integer);
569	    instr->set_src_reg(0, rs1, RegType::Integer);
570	    if (!is_imm) {
571	      instr->set_src_reg(1, rs2, RegType::Integer);
572	    }
573	  } break;
574	  case Opcode::B: {
575	    auto bit_11   = rd & 0x1;
576	    auto bits_4_1 = rd >> 1;
577	    auto bit_10_5 = funct7 & 0x3f;
578	    auto bit_12   = funct7 >> 6;
579	    auto imm12 = (bits_4_1 << 1) | (bit_10_5 << 5) | (bit_11 << 11) | (bit_12 << 12);
580	    auto addr = sext(imm12, width_i_imm+1);
581	    instr->set_op_type(BrType::BR);
582	    instr->set_args(IntrBrArgs{funct3, is_rvc, addr});
583	    instr->set_src_reg(0, rs1, RegType::Integer);
584	    instr->set_src_reg(1, rs2, RegType::Integer);
585	    instr->set_wstall(true);
586	  } break;
587	  case Opcode::JAL: {
588	    auto unordered  = code >> shift_funct3;
589	    auto bits_19_12 = unordered & 0xff;
590	    auto bit_11     = (unordered >> 8) & 0x1;
591	    auto bits_10_1  = (unordered >> 9) & 0x3ff;
592	    auto bit_20     = (unordered >> 19) & 0x1;
593	    auto imm20 = (bits_10_1 << 1) | (bit_11 << 11) | (bits_19_12 << 12) | (bit_20 << 20);
594	    auto addr = sext(imm20, width_j_imm+1);
595	    instr->set_op_type(BrType::JAL);
596	    instr->set_args(IntrBrArgs{0, is_rvc, addr});
597	    instr->set_dest_reg(rd, RegType::Integer);
598	    instr->set_wstall(true);
599	  } break;
600	  case Opcode::JALR: {
601	    auto imm12 = code >> shift_rs2;
602	    auto addr = sext(imm12, width_i_imm);
603	    instr->set_op_type(BrType::JALR);
604	    instr->set_args(IntrBrArgs{0, is_rvc, addr});
605	    instr->set_dest_reg(rd, RegType::Integer);
606	    instr->set_src_reg(0, rs1, RegType::Integer);
607	    instr->set_wstall(true);
608	  } break;
609	  case Opcode::L:
610	  case Opcode::FL:
611	  case Opcode::S:
612	  case Opcode::FS: {
613	    instr->set_fu_type(FUType::LSU);
614	    bool is_float = (op == Opcode::FL || op == Opcode::FS);
615	    bool is_load = (op == Opcode::L || op == Opcode::FL);
616	    {
617	      instr->set_src_reg(0, rs1, RegType::Integer);
618	      uint32_t imm12 = 0;
619	      if (is_load) {
620	        imm12 = code >> shift_rs2;
621	        instr->set_dest_reg(rd, is_float ? RegType::Float : RegType::Integer);
622	      } else {
623	        imm12 = (funct7 << width_reg) | rd;
624	        instr->set_src_reg(1, rs2, is_float ? RegType::Float : RegType::Integer);
625	      }
626	      auto offset = sext(imm12, width_i_imm);
627	      instr->set_op_type(is_load ? LsuType::LOAD : LsuType::STORE);
628	      instr->set_args(IntrLsuArgs{funct3, /*stride*/ 0, (int32_t)offset});
629	    }
630	  } break;
631	  case Opcode::FENCE: {
632	    instr->set_fu_type(FUType::LSU);
633	    instr->set_op_type(LsuType::FENCE);
634	    instr->set_args(IntrLsuArgs{0, 0, 0});
635	  } break;
636	  case Opcode::AMO: {
637	    instr->set_fu_type(FUType::LSU);
638	    uint32_t aq = (code >> shift_aq) & mask_aq;
639	    uint32_t rl = (code >> shift_rl) & mask_rl;
640	    switch (funct5) {
641	    case 0x00: instr->set_op_type(AmoType::AMOADD); break;
642	    case 0x01: instr->set_op_type(AmoType::AMOSWAP); break;
643	    case 0x02: instr->set_op_type(AmoType::LR); break;
644	    case 0x03: instr->set_op_type(AmoType::SC); break;
645	    case 0x04: instr->set_op_type(AmoType::AMOXOR); break;
646	    case 0x08: instr->set_op_type(AmoType::AMOOR); break;
647	    case 0x0c: instr->set_op_type(AmoType::AMOAND); break;
648	    case 0x10: instr->set_op_type(AmoType::AMOMIN); break;
649	    case 0x14: instr->set_op_type(AmoType::AMOMAX); break;
650	    case 0x18: instr->set_op_type(AmoType::AMOMINU); break;
651	    case 0x1c: instr->set_op_type(AmoType::AMOMAXU); break;
652	    default:
653	      std::abort();
654	    }
655	    instr->set_args(IntrAmoArgs{funct3, aq, rl});
656	    instr->set_dest_reg(rd, RegType::Integer);
657	    instr->set_src_reg(0, rs1, RegType::Integer);
658	    instr->set_src_reg(1, rs2, RegType::Integer);
659	  } break;
660	  case Opcode::SYS: {
661	    if (funct3 != 0) { // CSRRW/CSRRS/CSRRC — dispatched to the SFU's CSR sub-unit
662	      instr->set_fu_type(FUType::SFU);
663	      instr->set_dest_reg(rd, RegType::Integer);
664	      switch (funct3) {
665	      case 1: case 5: instr->set_op_type(CsrType::CSRRW); break;
666	      case 2: case 6: instr->set_op_type(CsrType::CSRRS); break;
667	      case 3: case 7: instr->set_op_type(CsrType::CSRRC); break;
668	      default:
669	        std::abort();
670	      }
671	      auto imm12 = code >> shift_rs2;
672	      if (funct3 < 5) {
673	        instr->set_src_reg(0, rs1, RegType::Integer);
674	        instr->set_args(IntrCsrArgs{0, 0, imm12});
675	      } else { // zimm
676	        instr->set_args(IntrCsrArgs{1, rs1, imm12});
677	      }
678	    } else { // ECALL/EBREACK/URET/SRET/MRET
