1105	        instr->set_args(IntrRtuArgs{});
1106	      } break;
1107	      default:
1108	        std::abort();
1109	      }
1110	    } break;
1111	#endif
1112	    default:
1113	      std::abort();
1114	    }
1115	    // FF<->SIMT interface-law structural assertion (gfx_v2 §1.3, P0): every FF
1116	    // op routed to the SFU must declare a scoreboarded / side-effect-free /
1117	    // known-violation handoff class, checked against its decoded destination.
1118	    gfx_doctrine::check(*instr);
1119	  } break;
1120	  default:
1121	    std::abort();
1122	  }
1123	
1124	  return instr;
1125	}
