#pragma once

#include <functional>
#include <memory>
#include <simobject.h>
#include "types.h"
#include "instr.h"
#include "lsu_unit.h"
#ifdef VX_CFG_EXT_TCU_ENABLE
#include "tcu_unit.h"
#endif
#ifdef VX_CFG_EXT_RTU_ENABLE
#include "rtu/rtu_unit.h"  // RtuUopGen (ISA v2 TRACE2/WAIT2 expansion)
#endif

namespace vortex {

class Core;
struct instr_trace_t;

///////////////////////////////////////////////////////////////////////////////

// Per-warp micro-op expander for multi-uop instructions (TCU WMMA/WGMMA).
// Simple instructions pass through unchanged.
class Sequencer : public SimObject<Sequencer> {
public:
  Sequencer(const SimContext& ctx, const char* name, Core* core, PoolAllocator<Instr, 64>& instr_pool);

  // Get current micro-op trace. Idempotent: returns same trace until advance().
  // For simple instructions, returns the input trace (pass-through).
  instr_trace_t* get(instr_trace_t* trace);

  // Advance to next micro-op. Returns true when all micro-ops have been issued.
  bool advance();

  // Drop any cached uop / macro-op state for this sequencer. Used by
  // Core::flush_warp_pipeline at async-trap entry: when the ibuffer is
  // flushed, the trace pointer this sequencer cached in state_.current_uop
  // (for the next issue) becomes dangling, so we have to drop it before
  // the trap handler issues.
  void flush() { state_.reset(); }

protected:
  void on_reset();

private:

  // uop generator callback: (macro_instr, uop_index) -> Instr::Ptr
  using GenFn = std::function<Instr::Ptr(const Instr&, uint32_t)>;

  struct State {
    bool     active;
    uint32_t uop_index;
    uint32_t uop_count;
    GenFn    gen_fn;
    instr_trace_t* current_uop;

    State() : active(false), uop_index(0), uop_count(0), current_uop(nullptr) {}

    void reset() {
      active = false;
      uop_index = 0;
      uop_count = 0;
      gen_fn = nullptr;
      current_uop = nullptr;
    }
  };

  Core* core_;
  State state_;
  LsuUopGen lsu_uop_gen_;
#ifdef VX_CFG_EXT_TCU_ENABLE
  TcuUopGen tcu_uop_gen_;
#endif
#ifdef VX_CFG_EXT_RTU_ENABLE
  RtuUopGen rtu_uop_gen_;
#endif

  friend class SimObject<Sequencer>;
};

} // namespace vortex

