300	    this->schedule();
301	
302	    ++perf_stats_.cycles;
303	    DPN(2, std::flush);
304	  }
305	
306	  // ----- Pipeline stages (private) -----
307	
308	  void schedule() {
309	    // profiling
310	    perf_stats_.active_warps += scheduler_->active_warps().count();
311	    perf_stats_.stalled_warps += scheduler_->stalled_warps().count();
312	
313	    // stop when fetch_latch cannot accept
314	    if (fetch_latch_.full())
315	      return;
316	
317	    // eligible warps: ibuffer not yet saturated
318	    WarpMask warp_mask;
319	    for (uint32_t w = 0, nw = VX_CFG_NUM_WARPS; w < nw; ++w) {
320	      if (ibuf_inflight_.at(w) < VX_CFG_IBUF_SIZE) {
321	        warp_mask.set(w);
322	      }
323	    }
324	
325	    auto trace = scheduler_->schedule(warp_mask);
326	    if (trace == nullptr) {
327	      ++perf_stats_.sched_idle;
328	      return;
329	    }
330	
331	    fetch_latch_.push(trace);
332	    DT(3, simobject_->name() << "-pipeline schedule: " << *trace);
333	    pending_instrs_.push_back(trace);
334	    ++ibuf_inflight_.at(trace->wid);
335	    perf_stats_.issued_warps += 1;
336	    perf_stats_.issued_threads += trace->tmask.count();
337	  }
338	
339	  void fetch() {
340	    perf_stats_.ifetch_latency += pending_ifetches_;
341	
342	  #ifdef VX_CFG_VM_ENABLE
343	    // With VM, fetch reads/writes the icache MMU's upstream channels.
344	    // The MMU translates and forwards to simobject_->icache_req_out
345	    // downstream (driven by SimChannel binding in the constructor).
346	    auto& icache_rsp = icache_mmu_->RspOut.at(0);
347	    auto& icache_req = icache_mmu_->ReqIn.at(0);
348	  #else
349	    auto& icache_rsp = simobject_->icache_rsp_in.at(0);
350	    auto& icache_req = simobject_->icache_req_out.at(0);
351	  #endif
352	
353	    // handle icache response — extract instruction word from the TLM line payload
354	    if (!icache_rsp.empty()){
355	      auto& mem_rsp = icache_rsp.peek();
356	      auto trace = pending_icache_.at(mem_rsp.tag);
357	      assert(mem_rsp.data && "icache response must carry line payload");
358	
359	    #ifdef VX_CFG_EXT_C_ENABLE
360	      // Decompressor classifies the rsp: emit-ready (sets trace->code) or
361	      // queues a refetch internally for cross-word 32-bit completion.
362	      bool emit = decompressor_->on_icache_rsp(trace, *mem_rsp.data);
363	      bool progressed = !emit || decode_latch_.try_push(trace);
364	    #else
365	      bool emit = true;
366	      bool progressed = false;
367	      if (decode_latch_.try_push(trace)) {
368	        uint32_t offset = trace->PC & (VX_CFG_MEM_BLOCK_SIZE - 1);
369	        std::memcpy(&trace->code, mem_rsp.data->data() + offset, sizeof(uint32_t));
370	        progressed = true;
371	      }
372	    #endif
373	      if (progressed) {
374	        if (emit) {
375	          DP(1, "Fetch: code=0x" << std::hex << trace->code << std::dec << ", cid=" << trace->cid
376	                 << ", wid=" << trace->wid << ", tmask=" << trace->tmask
377	                 << ", PC=0x" << std::hex << trace->PC << " (#" << std::dec << trace->uuid << ")");
378	        }
379	        DT(3, simobject_->name() << " icache-rsp: addr=0x" << std::hex << trace->PC << ", tag=0x" << mem_rsp.tag << std::dec << ", " << *trace);
380	        pending_icache_.release(mem_rsp.tag);
381	        icache_rsp.pop();
382	        --pending_ifetches_;
383	      }
384	    }
385	
386	    // send icache request — under EXT_C the FSM drains pending refetches
387	    // (cross-word completions) before fresh schedule traces.
388	    instr_trace_t* trace = nullptr;
389	    Word           req_addr = 0;
390	  #ifdef VX_CFG_EXT_C_ENABLE
391	    bool           from_refetch = false;
392	    {
393	      auto pick = decompressor_->pick_request(fetch_latch_.empty() ? nullptr
394	                                                              : fetch_latch_.peek());
395	      trace        = pick.trace;
396	      req_addr     = pick.addr;
397	      from_refetch = pick.from_refetch;
398	    }
399	  #else
400	    if (!fetch_latch_.empty()) {
401	      trace    = fetch_latch_.peek();
402	      req_addr = trace->PC;
403	    }
404	  #endif
405	    if (trace == nullptr)
406	      return;
407	
408	    // Avoid leaking icache tags when the request port back-pressures.
409	    if (pending_icache_.full()) {
410	      ++perf_stats_.fetch_stalls;
411	      return;
412	    }
413	
414	    MemReq mem_req;
415	    // Address goes downstream as VA. The icache MMU (under VX_CFG_VM_ENABLE)
416	    // substitutes PA before forwarding; with VM off, this is just the PA.
417	    mem_req.addr  = req_addr;
418	    // op defaults to MemOp::LD — icache request is a load.
419	    uint32_t tag = pending_icache_.allocate(trace);
420	    mem_req.tag   = tag;
421	    mem_req.hart_id   = trace->cid;
422	    mem_req.uuid  = trace->uuid;
423	    if (icache_req.try_send(mem_req)) {
424	      DT(3, simobject_->name() << " icache-req: addr=0x" << std::hex << mem_req.addr << ", tag=0x" << mem_req.tag << std::dec << ", " << *trace);
425	    #ifdef VX_CFG_EXT_C_ENABLE
426	      decompressor_->commit_request(from_refetch);
427	      if (!from_refetch) fetch_latch_.pop();
428	    #else
429	      fetch_latch_.pop();
